// Grabbed from https://github.com/radiofrance/svelte-component-actions/tree/main
export function useActions(node, actions) {
  if (!actions) return

  const actionReturns = actions.map(actionEntry => {
    const { fn, props } = actionEntry
    return fn(node, props)
  })

  return {
    update(newActions) {
      if (!newActions || newActions.length !== actionReturns.length) {
        throw new Error('You must not change the length of an actions array.')
      }
      newActions.forEach((actionEntry, i) => {
        const returnEntry = actionReturns[i]
        const { props } = actionEntry
        returnEntry?.update?.(props)
      })
    },
    destroy() {
      actionReturns.forEach(returnEntry => {
        returnEntry?.destroy?.()
      })
    },
  }
}
